question.solution:
import heapq

def top_k(nums, k):
    if k <= 0 or not nums:
        return []
    heap = []
    for value in nums:
        if len(heap) < k:
            heapq.heappush(heap, value)
        elif value > heap[0]:
            heapq.heapreplace(heap, value)
    return sorted(heap, reverse=True)

print(top_k([3, 2, 1, 5, 6, 4], 2))
print(top_k([3, 2, 3, 1, 2, 4, 5, 5, 6], 4))
print(top_k([], 3), top_k([1, 2], 0), top_k([1, 2], 5))
